package cache

import (
	"container/list"
	"sync"
)

type entry struct {
	key   string
	value int
}

// LRU is a fixed-capacity least-recently-used cache.
// Get counts as a use for recency. Put on an existing key updates the value
// and marks it most recently used without growing the cache. When the cache
// is full, Put evicts the least recently used entry.
type LRU struct {
	capacity  int
	entries   map[string]*list.Element
	list      *list.List
	mu        sync.Mutex
}

// NewLRU creates a new LRU cache with the given capacity.
func NewLRU(capacity int) *LRU {
	return &LRU{
		capacity: capacity,
		entries:  make(map[string]*list.Element),
		list:     list.New(),
	}
}

// Get returns the value stored for key and reports whether it was found.
// Accessing the key marks it as most recently used.
func (c *LRU) Get(key string) (int, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()

	elem, ok := c.entries[key]
	if !ok {
		return 0, false
	}
	c.list.MoveToFront(elem)
	return elem.Value.(*entry).value, true
}

// Put inserts or updates the value for key. Updating an existing key does not
// grow the cache. When the cache is full, the least recently used entry is
// evicted.
func (c *LRU) Put(key string, value int) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if elem, ok := c.entries[key]; ok {
		// Existing key: update value and mark most recently used.
		elem.Value.(*entry).value = value
		c.list.MoveToFront(elem)
		return
	}

	// New key: evict the least recently used entry if at capacity.
	for c.list.Len() >= c.capacity {
		lru := c.list.Back()
		if lru == nil {
			break
		}
		c.list.Remove(lru)
		delete(c.entries, lru.Value.(*entry).key)
	}

	elem := c.list.PushFront(&entry{key: key, value: value})
	c.entries[key] = elem
}

// Len returns the number of entries currently in the cache.
func (c *LRU) Len() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.list.Len()
}

